const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}
import('node:fs').then(({ readFileSync }) => {
  const text = readFileSync(0, 'utf8')
  const res = run(text)
  if (res.error) {
    process.stderr.write(`error: line ${res.line}: ${res.error}\n`)
    process.exit(2)
  }
  process.stdout.write(res.out)
})

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_.\/:-]+$/
const COUNT = /^(0|[1-9][0-9]*)$/

function run(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let started = false
  let lastTick = 0n
  let lineNo = 0
  const fail = (m) => { throw Object.assign(new Fail(m), { line: lineNo }) }
  const num = (s, field, least) => {
    if (!COUNT.test(s) || BigInt(s) < BigInt(least)) fail(`${field} must be an integer of at least ${least}`)
    return BigInt(s)
  }
  const out = []
  const stats = new Map()
  let tallyA = 0, tallyD = 0
  try {
    for (let i = 0; i < lines.length; i++) {
      lineNo = i + 1
      const t = lines[i].trim()
      if (t === '' || t[0] === '#') continue
      const f = t.split(/\s+/)
      const d = f[0]
      if (d === 'bucket' || d === 'window' || d === 'route') {
        if (started) fail('declarations must come before the first event')
      }
      if (d === 'bucket') {
        if (f.length !== 5) fail('expected bucket <name> <capacity> <refill> <per>')
        if (!NAME.test(f[1])) fail(`invalid policy name ${f[1]}`)
        const cap = num(f[2], 'capacity', 1)
        const refill = num(f[3], 'refill', 0)
        const per = num(f[4], 'per', 1)
        if (policies.has(f[1])) fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], { name: f[1], kind: 'bucket', cap, refill, per, st: new Map() })
      } else if (d === 'window') {
        if (f.length !== 4) fail('expected window <name> <limit> <span>')
        if (!NAME.test(f[1])) fail(`invalid policy name ${f[1]}`)
        const limit = num(f[2], 'limit', 0)
        const span = num(f[3], 'span', 1)
        if (policies.has(f[1])) fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], { name: f[1], kind: 'window', limit, span, st: new Map() })
      } else if (d === 'route') {
        if (f.length < 3) fail('expected route <prefix> <policy>...')
        if (!NAME.test(f[1])) fail(`invalid route prefix ${f[1]}`)
        if (routes.has(f[1])) fail(`prefix ${f[1]} is routed twice`)
        const list = []
        for (const n of f.slice(2)) {
          if (!policies.has(n)) fail(`unknown policy ${n}`)
          list.push(policies.get(n))
        }
        routes.set(f[1], list)
      } else if (d === 'event') {
        if (f.length !== 3) fail('expected event <tick> <key>')
        const tick = num(f[1], 'tick', 0)
        if (!NAME.test(f[2])) fail(`invalid key ${f[2]}`)
        if (tick < lastTick) fail(`tick ${tick} is before tick ${lastTick}`)
        started = true
        lastTick = tick
        const key = f[2]
        let best = null
        for (const [p, l] of routes) if (key.startsWith(p) && (best === null || p.length > best.length)) best = p
        let denied = null
        if (best !== null) {
          const list = routes.get(best)
          const states = list.map((p) => {
            let s = p.st.get(key)
            if (!s) {
              s = p.kind === 'bucket' ? { units: p.cap * p.per, last: tick } : { ticks: [] }
              p.st.set(key, s)
            }
            if (p.kind === 'bucket') {
              s.units += p.refill * (tick - s.last)
              const max = p.cap * p.per
              if (s.units > max) s.units = max
              s.last = tick
            } else {
              const cut = tick - p.span
              s.ticks = s.ticks.filter((x) => x > cut)
            }
            return s
          })
          for (let j = 0; j < list.length; j++) {
            const p = list[j], s = states[j]
            const ok = p.kind === 'bucket' ? s.units >= p.per : BigInt(s.ticks.length) < p.limit
            if (!ok) { denied = p.name; break }
          }
          if (denied === null) {
            list.forEach((p, j) => {
              if (p.kind === 'bucket') states[j].units -= p.per
              else states[j].ticks.push(tick)
            })
          }
        }
        let c = stats.get(key)
        if (!c) stats.set(key, (c = { a: 0, d: 0 }))
        if (denied === null) { c.a++; tallyA++ } else { c.d++; tallyD++ }
        out.push(`${tick} ${key} ${denied === null ? 'allow' : 'deny ' + denied}\n`)
      } else {
        fail(`unknown directive ${d}`)
      }
    }
  } catch (e) {
    if (e instanceof Fail) return { error: e.message, line: e.line }
    throw e
  }
  if (mode === 'replay') return { out: out.join('') }
  const keys = [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
  let s = ''
  for (const k of keys) s += `${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}\n`
  s += `total allowed=${tallyA} denied=${tallyD}\n`
  return { out: s }
}
